import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { update_user_rfid_details } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  mixins: [get_all_org_users],
  props: {
    rfidMapping: Boolean,
    rowInfo: Object
  },
  emits: ['update:rfidMapping', 'clicked', 'successMsg', 'errorMsg'],
  data() {
    return {
      loading: false,
      toggle_exclusive: "INTERNAL_USER",
      usersName: "",
      searchloc: "",
      VisitorName: "",
      loactionitems: []
    };
  },
  watch: {
    rfidMapping: {
      async handler() {
        if (this.rfidMapping == true) {
          this.toggle_exclusive = "INTERNAL_USER";
          await this.get_all_org_users();
          await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.loactionitems.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async delete_mutation() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(update_user_rfid_details, {
            input: {
              action_type: this.toggle_exclusive,
              user_id: this.toggle_exclusive != "VISITOR" ? this.usersName : undefined,
              visitor_name: this.toggle_exclusive == "VISITOR" ? this.VisitorName : undefined,
              rfid: this.rowInfo.rfid,
              swipe_id: this.rowInfo.swipe_id
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.update_user_rfid_details);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.$refs.form.resetValidation();
            this.$refs.form.reset();
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          // console.log(error)
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    }
  }
};
